DROP TABLE IF EXISTS `ads_keywords`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ads_keywords` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `provider` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `account_id` int NOT NULL,
  `campaign_id` int NOT NULL,
  `adgroup_id` int DEFAULT NULL,
  `external_keyword_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `keyword_text` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_type` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_negative` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

