INSERT INTO `plugins` VALUES (1,'GrapesJS Builder','GrapesJS Builder with MJML support for Mautic',0,'GrapesJsBuilderBundle','1.0.0','Mautic Community'),(2,'Gmail','Enables integrations with Gmail for email tracking',0,'MauticGmailBundle','1.0','Mautic'),(3,'Cloud Storage','Enables integrations with Mautic supported cloud storage services.',0,'MauticCloudStorageBundle','1.0','Mautic'),(4,'FullContact','Enables integration with FullContact for contact and company lookup',0,'MauticFullContactBundle','1.0','Mautic'),(5,'Clearbit','Enables integration with Clearbit for contact and company lookup',0,'MauticClearbitBundle','1.0','Werner Garcia'),(6,'Outlook','Enables integrations with Outlook for email tracking',0,'MauticOutlookBundle','1.0','Mautic'),(7,'Mautic tag manager bundle','Provides an interface for tags management.',0,'MauticTagManagerBundle','1.0','Leuchtfeuer'),(8,'CRM','Enables integration with Mautic supported CRMs.',0,'MauticCrmBundle','1.0','Mautic'),(9,'Mautic Focus','Drive visitor\'s focus on your website with Mautic Focus',0,'MauticFocusBundle','1.0','Mautic, Inc'),(10,'Social Media','Enables integrations with Mautic supported social media services.',0,'MauticSocialBundle','1.0','Mautic'),(11,'Zapier Integration','Zapier lets you connect Mautic with 1100+ other apps\n---\nLearn more about Zapier integration in the <a href=\"https://mautic.org/docs/en/plugins/zapier.html\">docs</a>. Make sure Mautic API and Basic Auth is enabled in the <a href=\"config/edit\" target=\"_blank\">configuration</a>.\n<br>\n<br>\nUse these predefined Zap templates as a starting point:\n<div id=\"zaps\"></div>\n<script src=\"https://zapier.com/apps/embed/widget.js?services=mautic&html_id=zaps\"></script>',0,'MauticZapierBundle','1.0','Mautic'),(12,'Email Marketing','Enables integration with Mautic supported email marketing services.',0,'MauticEmailMarketingBundle','1.0','Mautic'),(13,'Powertic SMS','Send SMS Payload to a Custom Endpoint.',0,'PowerticSmsBundle','3.0.0','Powertic'),(14,'Event Raffle','Sorteio de leads a partir de um formulário ou segmento para eventos.',0,'EventRaffleBundle','1.0.0','Mautic'),(15,'LetsWork CRM','Push Mautic contact data to LetsWork CRM via configurable HTTP webhook.',0,'LetsWorkCrmBundle','1.0.5','LetsWork'),(16,'SDR Call Tracker','Rastreamento de ligações SDR com push FCM para app Android.',0,'SdrCallTrackerBundle','1.0.7','Mautic'),(17,'Letswork CRM Analytics','Dashboard analytics premium para leads, conversao e pipeline.',0,'LetsworkAnalyticsBundle','2.0.0','Letswork'),(18,'Gemini Email AI','Generate editable email HTML with Google Gemini inside the Mautic visual builder.',0,'MauticGeminiEmailBundle','1.0.0','Mautic Community'),(19,'Mautic Ads Intelligence','Integra dados de anúncios com CRM para otimização por IA',0,'MauticAdsIntelligenceBundle','0.1.2','LetsWork');
